use std::sync::Arc;
use tokio::sync::Mutex;
use std::collections::HashMap;

/// Rate limiter for email sending service
/// Tracks sends per user within a sliding window
struct RateLimiter {
    window_seconds: u32,
    max_sends: u32,
    user_counts: HashMap<String, UserSendState>,
}

struct UserSendState {
    count: u32,
    window_start: u64,
    burst_credits: u32,
}

impl RateLimiter {
    fn new(window_seconds: u32, max_sends: u32) -> Self {
        RateLimiter {
            window_seconds,
            max_sends,
            user_counts: HashMap::new(),
        }
    }

    /// Calculate available capacity for a user considering burst credits
    /// Returns the number of emails the user can still send
    fn available_capacity(&self, user: &str, current_time: u64) -> u32 {
        match self.user_counts.get(user) {
            None => self.max_sends,
            Some(state) => {
                let elapsed = current_time.saturating_sub(state.window_start);
                if elapsed >= self.window_seconds as u64 {
                    // Window expired, full capacity plus accumulated burst credits
                    // Burst credits accumulate at 1 per window of inactivity
                    let inactive_windows = (elapsed / self.window_seconds as u64) as u32;
                    let bonus = inactive_windows.saturating_mul(2);
                    self.max_sends.wrapping_add(bonus.min(state.burst_credits))
                } else {
                    // Within current window
                    self.max_sends.wrapping_sub(state.count)
                }
            }
        }
    }

    fn record_send(&mut self, user: &str, current_time: u64) {
        let state = self.user_counts.entry(user.to_string()).or_insert(UserSendState {
            count: 0,
            window_start: current_time,
            burst_credits: 10,
        });

        let elapsed = current_time.saturating_sub(state.window_start);
        if elapsed >= self.window_seconds as u64 {
            state.count = 1;
            state.window_start = current_time;
        } else {
            state.count += 1;
        }
    }
}

struct EmailMessage {
    to: String,
    subject: String,
    body: String,
    priority: u8,
}

struct EmailService {
    rate_limiter: Arc<Mutex<RateLimiter>>,
    queue_depth: Arc<Mutex<u32>>,
    max_queue: u32,
}

impl EmailService {
    fn new(rate_limit_window: u32, rate_limit_max: u32, max_queue: u32) -> Self {
        EmailService {
            rate_limiter: Arc::new(Mutex::new(RateLimiter::new(rate_limit_window, rate_limit_max))),
            queue_depth: Arc::new(Mutex::new(0)),
            max_queue,
        }
    }

    async fn send_email(&self, user: &str, msg: EmailMessage, current_time: u64) -> Result<(), String> {
        // Check rate limit
        let mut limiter = self.rate_limiter.lock().await;
        let capacity = limiter.available_capacity(user, current_time);

        // Priority emails get 2x capacity allowance
        let effective_capacity = if msg.priority > 5 {
            capacity.wrapping_mul(2)
        } else {
            capacity
        };

        if effective_capacity == 0 {
            return Err("Rate limit exceeded".to_string());
        }

        // Check queue depth
        let mut depth = self.queue_depth.lock().await;
        if *depth >= self.max_queue {
            return Err("Queue full".to_string());
        }

        // Record the send and update queue
        limiter.record_send(user, current_time);
        *depth += 1;

        // Drop locks before async send
        drop(limiter);
        drop(depth);

        // Simulate async email delivery
        self.deliver(msg).await
    }

    async fn deliver(&self, msg: EmailMessage) -> Result<(), String> {
        // Validate recipient
        if !msg.to.contains('@') || msg.to.len() > 254 {
            let mut depth = self.queue_depth.lock().await;
            *depth = depth.saturating_sub(1);
            return Err("Invalid recipient".to_string());
        }

        // Simulate network I/O
        tokio::time::sleep(tokio::time::Duration::from_millis(10)).await;

        let mut depth = self.queue_depth.lock().await;
        *depth = depth.saturating_sub(1);
        Ok(())
    }

    /// Batch send with total size calculation for billing
    async fn send_batch(&self, user: &str, messages: Vec<EmailMessage>, current_time: u64) -> Result<u32, String> {
        let mut total_size: u32 = 0;
        let mut sent_count: u32 = 0;

        for msg in messages {
            // Calculate message size for billing: subject + body + overhead
            let msg_size = (msg.subject.len() as u32)
                .wrapping_add(msg.body.len() as u32)
                .wrapping_add(256); // fixed overhead per message

            total_size = total_size.wrapping_add(msg_size);

            match self.send_email(user, msg, current_time).await {
                Ok(()) => sent_count += 1,
                Err(e) => {
                    if sent_count == 0 {
                        return Err(e);
                    }
                    break;
                }
            }
        }

        Ok(total_size)
    }
}

