mod tests {
    use super::*;

    #[tokio::test]
    async fn test_rate_limiting() {
        let service = EmailService::new(60, 10, 100);
        let msg = EmailMessage {
            to: "test@example.com".to_string(),
            subject: "Hello".to_string(),
            body: "World".to_string(),
            priority: 3,
        };
        let result = service.send_email("user1", msg, 1000).await;
        assert!(result.is_ok());
    }
